/// Minimum committed offset across all consumers and consumer groups, with
/// the holder's identity. `None` when nothing has been committed, in which
/// case there is no deletion barrier. External groups never hold retention.
fn min_committed_offset(&self) -> Option<(u64, ConsumerKind, u32)> {
    let consumer_guard = self.consumer_offsets.pin();
    let group_guard = self.consumer_group_offsets.pin();
    let consumers = consumer_guard.iter().map(|(_, offset)| {
        (
            offset.offset.load(Ordering::Relaxed),
            offset.kind,
            offset.consumer_id,
        )
    });
    let groups = group_guard.iter().map(|(_, offset)| {
        (
            offset.offset.load(Ordering::Relaxed),
            offset.kind,
            offset.consumer_id,
        )
    });
    consumers.chain(groups).min_by_key(|(offset, _, _)| *offset)

fn retention_is_ready(&mut self, through: u64) -> bool {
    if self.log.segments().len() < 2 {
        self.maintenance.retention = None;
        return false;
    }
    let segment = &self.log.segments()[0];
    if !segment.sealed || segment.end_offset > through {
        self.maintenance.retention = None;
        return false;
    }
    if let Some((barrier, kind, consumer_id)) = self.min_committed_offset()
        && segment.end_offset > barrier
    {
        warn!(namespace_raw = self.namespace().inner(), start_offset = segment.start_offset, end_offset = segment.end_offset, barrier, %kind, consumer_id, "segment retained: blocked by committed consumer offset");
        self.maintenance.retention = None;
        return false;

/// Re-anchor the append point after boot re-seeded the offset counter above
/// what the recovered segment chain holds.
///
/// A hole INSIDE a segment is not survivable: `recover_segment_bounds` walks
/// a segment from its FILENAME with a running `expected_offset` and REFUSES
/// at the first offset that does not continue it (`OffsetDiscontinuity`),
/// which on a solo group tombstones the partition. A surviving index does not
/// help: a first entry that is not the file-name offset makes recovery
/// discard the index and walk from byte 0, reaching the same refusal. On a
/// segment BOUNDARY every reader copes -- absolute offsets in the index,
/// `disk_poll_start` walking on into later segments, and a chain guard that
/// admits a forward gap the reservation covers.

/// With automatic commits enabled, a new consumer offset key can be
/// rejected with `TooManyConsumerOffsets` at the partition's configured
/// limit. That poll returns no messages. Existing keys remain writable,
/// and polling without automatic commits does not allocate a stored offset.

/// Binary clients cache the route of an offset write with the partition context it reported.
/// After another client deletes and recreates the partition, a write without a caller context
/// ([`Self::store_consumer_offset`], [`Self::delete_consumer_offset`]) can fail once with
/// [`IggyError::HistoryUnavailable`] (87), or with [`IggyError::ConsumerGroupPartitionNotOwned`]
/// (5009) for a consumer group. The failed route is dropped, so the next call routes again and
/// takes the new context. [`Self::store_consumer_position`] carries the caller's context, so it
/// keeps getting the refusal for that context.

/// Delete the consumer offset for a specific consumer or consumer group for the given stream and topic by unique IDs or names.
///
/// Authentication is required, and the permission to poll the messages.
/// A missing durable key returns [`IggyError::ConsumerOffsetNotFound`] (3021).
/// Missing numeric and named groups return codes 5000 and 5003 respectively.
/// A replica unable to admit the request returns [`IggyError::TransientNotAccepted`].
/// Deletion does not allocate a new key and is allowed at the offset limit.
async fn delete_consumer_offset(
    &self,
    consumer: &Consumer,
    stream_id: &Identifier,
    topic_id: &Identifier,
    partition_id: Option<u32>,
) -> Result<(), IggyError>;

/**
 * Validate that the AutoCDC key columns the flow expects match the keys recorded in the
 * existing auxiliary table at [[auxIdent]] as a set: same arity, same set of names (per the
 * session resolver), same per-name `dataType`s.
 */
private def validateNoAutoCdcKeyDrift(
    existingAuxTable: CatalogTable,
    auxIdent: TableIdentifier): Unit = {
  val resolver = spark.sessionState.conf.resolver
  val existingAuxSchema = CatalogV2Util.v2ColumnsToStructType(existingAuxTable.columns())

  // Resolve the flow-declared (expected) keys from [[auxiliaryTableSchema]]. We deliberately
  // do not look them up in [[existingAuxSchema]] - that's the recorded side, and conflating
  // the two sides would mask drift. See [[expectedAuxiliaryKeyFields]].
  val expectedKeyFields: Seq[StructField] = expectedAuxiliaryKeyFields
  val recordedKeyNames = parseRecordedKeyColumnNames(existingAuxTable, auxIdent)
  val recordedKeyFields: Seq[StructField] = recordedKeyNames.map { name =>
    existingAuxSchema.fields
      .find(field => resolver(field.name, name))
      .getOrElse(
        // Either an implementation bug or, more likely, the user has corrupted the auxiliary
        // table schema (e.g. dropped the key column). The remedy is full-refresh in either
        // case.
        throw new AnalysisException(
          errorClass = "AUTOCDC_INVALID_STATE.AUXILIARY_TABLE_KEY_COLUMN_MISSING",
          messageParameters = Map(
            "flowName" -> identifier.unquotedString,
            "auxTableName" -> auxIdent.unquotedString,
            "keyColumnName" -> name,
            "propertyName" -> AutoCdcAuxiliaryTable.keyColumnNamesProperty
          )
        )
      )
  }

  val drifted =
    // Arity drift (added or dropped keys).
    recordedKeyFields.length != expectedKeyFields.length ||
    // Name or dataType drift: every expected key must have a same-name (resolver-aware)
    // recorded counterpart with an equivalent dataType. Columns changing nullability and
    // metadata in the schema are intentionally tolerated, although null key values during
    // microbatch execution will be invalidated regardless.
    expectedKeyFields.exists { expected =>
      recordedKeyFields.find(rf => resolver(rf.name, expected.name)) match {
        case None => true
        case Some(recorded) => !recorded.dataType.sameType(expected.dataType)
      }
    }

  if (drifted) {
    throw new AnalysisException(
      errorClass = "AUTOCDC_INVALID_STATE.KEY_SCHEMA_DRIFT",
      messageParameters = Map(
        "flowName" -> identifier.unquotedString,
        "auxTableName" -> auxIdent.unquotedString,
        "expectedKeySchema" -> StructType(expectedKeyFields).toDDL,
        "recordedKeySchema" -> StructType(recordedKeyFields).toDDL
      )

